import{_ as t,o as a,c as e,ae as s}from"./chunks/framework.BX6FPmO9.js";const m=JSON.parse('{"title":"Git 與版本控制","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/git-version-control.md","filePath":"conventions/git-version-control.md"}'),o={name:"conventions/git-version-control.md"};function n(l,i,r,c,h,d){return a(),e("div",null,[...i[0]||(i[0]=[s(`<h1 id="git-與版本控制" tabindex="-1">Git 與版本控制 <a class="header-anchor" href="#git-與版本控制" aria-label="Permalink to &quot;Git 與版本控制&quot;">​</a></h1><p><strong>類型</strong>：spec | <strong>權重</strong>：1</p><p>本文件說明 Commit 慣例、刪除檔案時保留操作紀錄的方式，以及空資料夾處理。</p><hr><h2 id="commit-慣例" tabindex="-1">Commit 慣例 <a class="header-anchor" href="#commit-慣例" aria-label="Permalink to &quot;Commit 慣例&quot;">​</a></h2><p>採用 <strong>Conventional Commits</strong>（commitlint 強制）：</p><ul><li><code>feat:</code> 新功能</li><li><code>fix:</code> 修正 bug</li><li><code>chore:</code> 工具或維護</li><li><code>docs:</code> 文件更新</li><li><code>refactor:</code> 重構</li><li><code>test:</code> 測試</li></ul><p>詳見 <a href="./../../CONTRIBUTING.html">CONTRIBUTING.md</a>。</p><hr><h2 id="刪除檔案-使用-git-rm" tabindex="-1">刪除檔案：使用 git rm <a class="header-anchor" href="#刪除檔案-使用-git-rm" aria-label="Permalink to &quot;刪除檔案：使用 git rm&quot;">​</a></h2><p>要保留 Git 操作紀錄時，請用 <strong><code>git rm &lt;path&gt;</code></strong> 刪除已追蹤的檔案，不要只從檔案系統刪除。</p><ul><li>好處：staging 與 commit 會明確記錄「刪除」，方便協作與 AI 輔助時有一致紀錄。</li><li>適用情境：重構搬檔、清理舊元件、移除廢棄 API 等。</li></ul><p>範例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app/components/old/Component.tsx</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 若有多檔可一次指定</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app/components/chat/ChatInterface.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app/components/lui/ChatBubble.tsx</span></span></code></pre></div><hr><h2 id="空資料夾" tabindex="-1">空資料夾 <a class="header-anchor" href="#空資料夾" aria-label="Permalink to &quot;空資料夾&quot;">​</a></h2><p>Git <strong>不追蹤空目錄</strong>。刪除目錄內最後一個檔案後，該路徑會從 repo 樹狀結構消失。</p><ul><li>本機若留下空資料夾，可手動用 <code>rmdir</code>（Windows）或 <code>rm -rf &lt;dir&gt;</code>（Unix）清除。</li><li>無需對空資料夾執行 <code>git rm</code>（Git 沒有空目錄的 tracked 物件）。</li></ul><hr><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./../../CONTRIBUTING.html">CONTRIBUTING.md</a>：Commit message、Quality checks</li><li><a href="./../../AGENTS.html">AGENTS.md</a>：Coding agent 入口，含 Git 注意事項摘要</li></ul>`,21)])])}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
